 subroutine ev2gm2m(dist,v2b,g2b,imol,igrad,n)

    implicit none

    integer,intent(in) :: imol, igrad
    integer,intent(in) :: n
    double precision,intent(in)  :: dist(n*(n-1)/2)
    double precision,intent(out) :: v2b(6), g2b(6,3)
    double precision :: v(6), grad(6)
    double precision :: r
    integer :: i,j

    ! dist should be in Ang
    ! v2b is in kcal/mol
    ! grad2b is in kcal/molAng

    ! V0 is 120.17443 kcal/mol
    v2b = 0.0d0 !120.17443d0/23.061d0
    g2b = 0.0d0
    do i=1,n*(n-1)/2
      r=dist(i) !*0.529177d0
      call ev2gm2(r,v,grad,imol,igrad)
      v2b = v2b + v/23.061d0
      if (igrad.eq.1) then
        do j=1,6
          g2b(j,i) = grad(j)/(23.061d0) !/0.529177d0)
        enddo
      endif
    enddo

    end subroutine ev2gm2m
    
  subroutine ev2gm2(r,v,grad,imol,igrad) 
    !**********************************************************************
    !
    ! Compute the diatomic potential of groupd-state triplet O2
    !
    ! References: J. Chem. Phys. 132, 074307 (2010)
    !
    ! Input:  r      interatomic distance in Angstrom
    ! Output: V      potential in kcal/mol
    !         grad   gradient (kcal/mol)/Angstrom
    !
    !**********************************************************************
          implicit none
    
          integer,intent(in) :: imol, igrad
          double precision,intent(in)  :: r
          double precision,intent(out) :: v(6), grad(6)
    ! Parameters of analytical even-tempered Gaussian expansions for the
    ! ground state potential energy curve of O2 CBS+SR+SO+CV.
    ! Units: alpha in Angstrom^-2, beta=dimensionless, as_k in milihartree.
          double precision :: alpha,beta,as(0:7)
          double precision :: gam, del
          integer :: i,j,k 
    
          v=0.0d0
          grad=0.0d0
    
    ! list of considered states in 5A'' symmetry
    ! V(1) - O2(3Sig_g^-) + O(3P)
    ! V(2) - O2(3Del_u)   + O(3P)
    ! V(3) - O2(3Del_u)   + O(3P)
    ! V(4) - O2(3Del_u)   + O(3P)
    ! V(5) - O2(3Sig_u^+) + O(3P)
    ! V(6) - O2(3Sig_u^+) + O(3P)
    
    
         do i=1,6
          if (i.eq.1) then
    
          ! O2 X 3Sig_g^-
                  as(0) =       71492.0825
          as(1) =       -96462.2714
          as(2) =       124669.5962
          as(3) =       -117580.8781
          as(4) =       106349.5143
          as(5) =       -72387.5754
          as(6) =       37409.2123
          as(7) =       -10165.7980
          alpha =       12.3688
          beta =        0.7421
          else if ((i.eq.2).or.(i.eq.3).or.(i.eq.4)) then
      ! O2 A' 3Del_u
                  ! O2 C 3Del_u
           as(0) =      7133519.1248
           as(1) =      -21842782.2951
           as(2) =      18821411.2536
           as(3) =      4796852.3950
           as(4) =      -12377676.7323
           as(5) =      -343577.2019
           as(6) =      5875440.3400
           as(7) =      -2047566.0842
           alpha =      3.3916
           beta =       0.9413
  
        else if ((i.eq.5).or.(i.eq.6)) then
      ! O2 A 3Sig_u^+
                alpha =  0.1044
          beta =   5.4643
          as(0) =  0.0105
          as(1) =  -75.2131
          as(2) =  5884.3053
          as(3) =  241893.1847
          as(4) =  6995.4774
          as(5) =  -2620.5113
          as(6) =  -14514.4843
          as(7) =  -10838.5723
          endif
    
          do k=0,7
           v(i)= v(i) + as(k)*dexp(-alpha*beta**k*r**2)
          enddo
          if ((i.eq.13).or.(i.eq.14).or.(i.eq.15).or.(i.eq.16)) then
           v(i)= v(i) + gam*dexp(-del*(r-1.7d0)**2)
          endif
    
    ! Compute the gradient if needed
          if (igrad.eq.1) then
           do k=0,7
            grad(i)=grad(i)-2.d0*as(k)*alpha*beta**k*r*dexp(-alpha*beta**k*r**2)
           enddo
          if ((i.eq.13).or.(i.eq.14).or.(i.eq.15).or.(i.eq.16)) then
            grad(i)=grad(i)-2.0d0*del*gam*(r-1.7d0)*dexp(-del*(r-1.7d0)**2)
           endif
          endif
    
          enddo
    
          return
          end subroutine ev2gm2
    


